from funcy import decorator

# Simple decorator that just calls through
@decorator
def simple(call):
    print(f"Before calling {call._func.__name__}")
    result = call()
    print(f"After calling")
    return result

# Function with keyword-only args
@simple
def test_kwonly(a, b, *, c=1):
    return a + b + c

try:
    result = test_kwonly(1, 2, c=3)
    print(f"result: {result}")
except Exception as e:
    import traceback
    traceback.print_exc()

# Also test without kwonly
@simple
def test_normal(a, b, c=1):
    return a + b + c

try:
    result = test_normal(1, 2, c=3)
    print(f"normal result: {result}")
except Exception as e:
    import traceback
    traceback.print_exc()
EOF
